    await tab.goto(origin+'/login',{waitUntil:'domcontentloaded',timeout:20000});
    await tab.getByRole('textbox',{name:'Email sinh viên'}).fill('hard-load-20261121-'+index+'@student.edu.ctu.vn');
    await tab.getByRole('button',{name:'Đăng nhập',exact:true}).click();
    await tab.waitForURL('**/chat',{timeout:20000});
